def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    # The solid full-width line is a boundary guide. Its color is kept; draw color 8
    # on the nearest blank row/column on the figure side of that guide.
    for r,row in enumerate(grid):
        if len(set(row))==1 and row[0]!=bg:
            occupied=[rr for rr in range(h) if rr!=r and any(v not in (bg,row[0]) for v in grid[rr])]
            if occupied:
                near=max((rr for rr in occupied if rr<r),default=None) if r>min(occupied) else min((rr for rr in occupied if rr>r),default=None)
                if near is not None:
                    target=near+1 if near<r else near-1
                    out[target]=[8]*w
            return out
    # Solid vertical guide at edge, as in demo 1/2: stripe in adjacent gap column.
    for c in range(w):
        if len({grid[r][c] for r in range(h)})==1 and grid[0][c]!=bg:
            figurecols=[cc for cc in range(w) if any(grid[r][cc] not in (bg,grid[0][c]) for r in range(h))]
            if figurecols:
                target=max(figurecols)+1 if max(figurecols)<c else min(figurecols)-1
                if 0<=target<w:
                    for rr in range(h):out[rr][target]=8
            return out
    return out
